={
  "system_instruction": {
    "parts": [{
      "text": "Bạn là Intent Classifier cho hệ thống ChatOps. Phân tích câu lệnh và trả về JSON thuần túy (không dùng markdown code block). Format bắt buộc: {\"intent\": \"standup|run-test|recon|jira|squash|sync|help\", \"params\": {\"issueKey\": \"...\"}}. Quy tắc: standup=báo cáo/daily/sprint, run-test=chạy test/kiểm thử (params.issueKey bắt buộc), recon=đối chiếu dữ liệu/watchdog, jira=lấy issue/vé (params.issueKey bắt buộc), squash=đẩy test case, sync=đồng bộ code/repo/pull, help=mặc định khi không rõ."
    }]
  },
  "contents": [{
    "parts": [{
      "text": " Câu lệnh từ Mattermost: " + ($json.body.text || '')
    }]
  }],
  "generationConfig": {
    "temperature": 0.1,
    "maxOutputTokens": 256,
    "responseMimeType": "application/json"
  }
}

parameters.jsCode:
const input = $input.first();
const response = (input && input.json) || {};
const originalText = $('Webhook (Mattermost Slash Command)').first()?.json?.body?.text || '';

// ── Hàm fallback bóc tách từ khóa bằng Regex khi AI gặp sự cố ─────────────────
function fallbackParse(text) {
  const clean = (text || '').toLowerCase().trim();
  if (clean.includes('standup') || clean.includes('daily')) return { intent: 'standup' };
  if (clean.includes('recon')) return { intent: 'recon' };
  if (clean.includes('test') || clean.includes('kiểm thử')) {
    const match = clean.match(/([a-z0-9]+-[0-9]+)/i);
    return { intent: 'run-test', params: { issueKey: match ? match[1].toUpperCase() : '' } };
  }
  if (clean.includes('sync') || clean.includes('pull') || clean.includes('đồng bộ')) return { intent: 'sync' };
  if (clean.includes('squash')) return { intent: 'squash' };
  const jiraMatch = (text || '').match(/([A-Za-z0-9]+-[0-9]+)/i);
  if (jiraMatch || clean.includes('jira') || clean.includes('vé') || clean.includes('issue')) {
    return { intent: 'jira', params: { issueKey: jiraMatch ? jiraMatch[1].toUpperCase() : '' } };
  }
  return { intent: 'help' };
}

// Nếu Gemini API gặp lỗi (hết quota, sai key, timeout)
if (response.error || (response.status && response.status >= 400)) {
  const fallback = fallbackParse(originalText);
  return [{ json: { ...fallback, _geminiError: response.error?.message || 'Lỗi Gemini API' } }];
}

try {
  const rawText = response.candidates?.[0]?.content?.parts?.[0]?.text || '';
  let data;
  if (typeof rawText === 'object') {
    data = rawText;
  } else {
    const cleanJson = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    data = JSON.parse(cleanJson);
  }

  // Validate intent hợp lệ
  const validIntents = ['standup', 'run-test', 'recon', 'jira', 'squash', 'sync', 'help'];
  if (!validIntents.includes(data.intent)) data.intent = 'help';

  // Đảm bảo trích xuất issueKey nếu intent là jira mà AI quên trích
  if ((data.intent === 'jira' || data.intent === 'run-test') && (!data.params || !data.params.issueKey)) {
    const m = originalText.match(/([A-Za-z0-9]+-[0-9]+)/i);
    if (m) {
      data.params = data.params || {};
      data.params.issueKey = m[1].toUpperCase();
    }
  }

  return [{ json: data }];
} catch(e) {
  return [{ json: fallbackParse(originalText) }];
}

